#include<bits/stdc++.h>
using namespace std;
#define DEBUG 0
typedef long long ll;
typedef pair<int,int> pii;
typedef pair<ll,ll> pll;
#define fore(i,ii,iii) for(int i=ii;i<iii;i++)
#define pb push_back
#define SZ(a) ((int)(a).size())
#define mset(a,b) memset(a,b,sizeof(a));
#define ALL(a) a.begin(),a.end()
#define fst first
#define snd second

const int MAXN=50*100+15;
int SRC = MAXN-1;
int SNC = MAXN-2;

typedef ll tf; const tf INFFLUJO=1e14;
typedef ll tc; const tc INFCOSTO=1e14;

class MinCostMaxFlow {
public:
    struct Edge {
        int u,v; tf cap,flow; tc cost;
        tf rem() { return cap-flow; }
    };
    int n;
    vector<vector<int>> g;
    vector<Edge> e;
    vector<tc> dist;
    vector<int> pre;
    vector<tf> cap;
    vector<bool> inq;
    tf mxflow; tc mncost;

    MinCostMaxFlow(int n) : n(n), g(n), dist(n), pre(n), cap(n), inq(n) {}

    void add_edge(int u, int v, tf cap, tc cost) {
        if(DEBUG) {
            string dem=to_string(u),pen=to_string(v);
            if(u==SRC)dem="SRC";
            if(u==SNC)dem="SINC";
            if(v==SRC)pen="SRC";
            if(v==SNC)pen="SINC";
            cout<<"add edge: "<<dem<<" "<<pen<<" "<<cap<<" "<<cost<<endl;
        }
        g[u].pb(SZ(e)); e.pb({u,v,cap,0,cost});
        g[v].pb(SZ(e)); e.pb({v,u,0,0,-cost});
    }

    void flow(int s, int t) {
        mxflow = mncost = 0;
        while(1) {
            fill(ALL(dist), INFCOSTO); dist[s] = 0;
            fill(ALL(pre), -1); pre[s] = 0;
            fill(ALL(cap), 0); cap[s] = INFFLUJO;
            fill(ALL(inq), false);
            queue<int> q; q.push(s); inq[s] = true;
            while(!q.empty()) {
                int u = q.front(); q.pop(); inq[u] = false;
                for(int idx : g[u]) {
                    Edge &E = e[idx];
                    if(E.rem() && dist[E.v] > dist[u] + E.cost + 1e-9) {
                        dist[E.v] = dist[u] + E.cost;
                        pre[E.v] = idx;
                        cap[E.v] = min(cap[u], E.rem());
                        if(!inq[E.v]) { q.push(E.v); inq[E.v] = true; }
                    }
                }
            }
            if(pre[t] < 0) break;
            mxflow += cap[t];
            mncost += cap[t] * dist[t];
            for(int v = t; v != s; v = e[pre[v]].u) {
                e[pre[v]].flow += cap[t];
                e[pre[v]^1].flow -= cap[t];
            }
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    ll n,m,k,c,d;
    cin>>n>>m>>k>>c>>d;
    int MAXT = n + k;
    if(DEBUG) cout<<"MAXT: "<<MAXT<<endl;
    MinCostMaxFlow mcmf(MAXN);
    vector<int> a(k);
    fore(i,0,k) {
        cin>>a[i]; a[i]--;
        mcmf.add_edge(SRC, a[i]*MAXT, 1, 0);
    }
    fore(j,0,MAXT) mcmf.add_edge(j, SNC, k, 0);
    fore(i,0,m) {
        int x,y; cin>>x>>y; x--,y--;
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            mcmf.add_edge(x*MAXT+j, y*MAXT+j+1, 1, c + d*(2*K-1));
        }
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            mcmf.add_edge(y*MAXT+j, x*MAXT+j+1, 1, c + d*(2*K-1));
        }
    }
    fore(i,0,n) {
        fore(j,0,MAXT-1) fore(K,1,k+1) {
            mcmf.add_edge(i*MAXT+j, i*MAXT+j+1, 1, c);
        }
    }
    mcmf.flow(SRC, SNC);
    if(DEBUG) cout<<"mncost: "<<mcmf.mncost<<" mxflow: "<<mcmf.mxflow<<endl;
    cout<<mcmf.mncost<<endl;
}
